import { useContext } from 'react'
import {
  Button as AriaButton,
  Calendar as AriaCalendar,
  CalendarStateContext,
  CalendarCell as AriaCalendarCell,
  CalendarGrid as AriaCalendarGrid,
  DateInput as AriaDateInput,
  DatePicker as AriaDatePicker,
  DateSegment as AriaDateSegment,
  FieldError as AriaFieldError,
  Group as AriaGroup,
  Label as AriaLabel,
  Popover as AriaPopover,
  Text as AriaText,
} from 'react-aria-components'
import type {
  ButtonProps as AriaButtonProps,
  CalendarCellProps as AriaCalendarCellProps,
  CalendarGridProps as AriaCalendarGridProps,
  CalendarHeadingProps as AriaCalendarHeadingProps,
  CalendarProps as AriaCalendarProps,
  DateInputProps as AriaDateInputProps,
  DatePickerProps as AriaDatePickerProps,
  DateSegmentProps as AriaDateSegmentProps,
  DateValue,
  FieldErrorProps as AriaFieldErrorProps,
  GroupProps as AriaGroupProps,
  LabelProps as AriaLabelProps,
  PopoverProps as AriaPopoverProps,
  TextProps as AriaTextProps,
} from 'react-aria-components'

import {
  DATE_HEADING,
  DATE_MENU,
  DATE_ROOT,
  DATE_SEGMENT,
  DATE_TRIGGER,
  DATE_CELL,
  DateCalendarChrome,
  DateCaret,
  useVisibleRangeLabel,
} from '../date'
import {
  ERROR,
  FIELD_SIZES,
  GROUP,
  HINT,
  ICON,
  ICON_POSITIONS,
  INPUT,
  LABEL,
} from '../field'
import type { FieldSize, IconPosition } from '../field'

/**
 * The sheet has no date picker in it, so this is the first component here that was not copied
 * from one — which means the rules it follows are the sheet's *language* rather than its markup:
 * square, mono, the field's own hairline and focus, the select's menu surface, and the accent
 * reserved for the thing that is chosen.
 */

/** The sheet's `.ds-select-menu`, the same surface a select's list opens on. */

/**
 * A segment of the date — the month, the day, the year. It takes the field's text colour and its
 * placeholder weight, and marks the segment being edited with the same faint wash the sheet puts
 * behind a hovered option rather than with the accent: a field's focus is a teal *border*, and
 * filling it in here would say "chosen" about a segment that is only being typed.
 */

/**
 * A day. Square, like everything else here, and the chosen one is a teal fill carrying `ink` —
 * the same pair the sheet uses for a checked box and a selected row.
 *
 * Outside the month, unavailable and today are three different things and get three different
 * treatments: dimmed, dimmed *and* struck through, and outlined in the accent without being
 * filled. Leaving today looking exactly like the rest is the usual way a calendar makes someone
 * ask what today is.
 */

/**
 * A segment of a date — a month, a day, a year. Taken from React Aria's own render prop rather
 * than re-declared, so it cannot drift from the signature it has to match.
 */
type Segment = Parameters<NonNullable<AriaDateInputProps['children']>>[0]

export interface DatePickerProps<T extends DateValue> extends Omit<
  AriaDatePickerProps<T>,
  | 'isDisabled'
  | 'isReadOnly'
  | 'isRequired'
  | 'isInvalid'
  | 'children'
  | 'className'
> {
  /** React 19 passes `ref` as an ordinary prop, so no `forwardRef` wrapper. */
  ref?: React.Ref<HTMLDivElement>
  /** Sizes the control the same way a field is sized, through the shared tokens. */
  size?: FieldSize
  /** Disables the control. This is a React Aria prop — there is no `disabled`. */
  isDisabled?: AriaDatePickerProps<T>['isDisabled']
  isReadOnly?: AriaDatePickerProps<T>['isReadOnly']
  isRequired?: AriaDatePickerProps<T>['isRequired']
  isInvalid?: AriaDatePickerProps<T>['isInvalid']
  /** The value. `onChange` gives a `DateValue`, not a string. */
  value?: AriaDatePickerProps<T>['value']
  defaultValue?: AriaDatePickerProps<T>['defaultValue']
  onChange?: AriaDatePickerProps<T>['onChange']
  /** The earliest and latest days that may be chosen. */
  minValue?: AriaDatePickerProps<T>['minValue']
  maxValue?: AriaDatePickerProps<T>['maxValue']
  className?: string
  /**
   * `DatePicker.Label`, `DatePicker.Group`, then the hint and error. The calendar is drawn for
   * you, and there is no slot to pass for it.
   */
  children?: React.ReactNode
}

export interface DatePickerLabelProps extends AriaLabelProps {
  children?: React.ReactNode
}

export interface DatePickerGroupProps extends Omit<
  AriaGroupProps,
  'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface DatePickerInputProps extends Omit<
  AriaDateInputProps,
  'children' | 'className'
> {
  className?: string
  /**
   * How to draw each segment. Optional — the segments are drawn for you — and it is a render
   * prop rather than children, because that is what React Aria's date input takes: it calls this
   * once per segment with the segment itself.
   */
  children?: (segment: Segment) => React.ReactElement
}

export interface DatePickerSegmentProps extends Omit<
  AriaDateSegmentProps,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface DatePickerButtonProps extends Omit<
  AriaButtonProps,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface DatePickerPopoverProps extends Omit<
  AriaPopoverProps,
  'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface DatePickerCalendarProps extends Omit<
  AriaCalendarProps<DateValue>,
  'children' | 'className'
> {
  className?: string
  /** The calendar's contents. Optional — the whole month is drawn for you. */
  children?: React.ReactElement | React.ReactElement[]
}

export interface DatePickerHeadingProps extends AriaCalendarHeadingProps {
  children?: React.ReactNode
}

export interface DatePickerGridProps extends Omit<
  AriaCalendarGridProps,
  'children' | 'className'
> {
  className?: string
  /** The grid's rows — usually a header and a body. */
  children?: React.ReactElement | React.ReactElement[]
}

export interface DatePickerCellProps extends Omit<
  AriaCalendarCellProps,
  'children' | 'className'
> {
  className?: string
  children?: React.ReactNode
}

export interface DatePickerIconProps extends React.HTMLAttributes<HTMLSpanElement> {
  position?: IconPosition
  className?: string
  children?: React.ReactNode
}

export interface DatePickerHintProps extends AriaTextProps {
  children?: React.ReactNode
}

export interface DatePickerFieldErrorProps extends AriaFieldErrorProps {
  children?: React.ReactNode
}

/**
 * The legend. Use it as `DatePicker.Label`.
 *
 * Exported as `DatePickerLabel` only so tooling can resolve it; consume the compound form
 * `DatePicker.Label`.
 */
export function DatePickerLabel({
  className,
  children,
  ...props
}: DatePickerLabelProps) {
  return (
    <AriaLabel
      className={[LABEL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaLabel>
  )
}

/**
 * Wraps the segments and the button. Use it as `DatePicker.Group`; it is what leaves room for the
 * chevron, through the same `data-slot` rules a field's affixes use.
 *
 * Exported as `DatePickerGroup` only so tooling can resolve it; consume the compound form
 * `DatePicker.Group`.
 */
export function DatePickerGroup({
  className,
  children,
  ...props
}: DatePickerGroupProps) {
  return (
    <AriaGroup
      className={[GROUP, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaGroup>
  )
}

/**
 * The date itself, as editable segments. Use it as `DatePicker.Input`; the field's hairline,
 * height and focus come from the shared anatomy, so it lines up with a `TextField` beside it.
 *
 * Exported as `DatePickerInput` only so tooling can resolve it; consume the compound form
 * `DatePicker.Input`.
 */
export function DatePickerInput({
  className,
  children,
  ...props
}: DatePickerInputProps) {
  return (
    <AriaDateInput
      data-slot="input"
      className={[INPUT, 'flex items-center', className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children ??
        ((segment: Segment) => (
          <DatePickerSegment key={segment.type} segment={segment} />
        ))}
    </AriaDateInput>
  )
}

/**
 * One segment of the date. Input` draws them for you.
 *
 * **Internal.** `DatePicker` draws one itself; it is not a published slot.
 */
export function DatePickerSegment({
  className,
  children,
  ...props
}: DatePickerSegmentProps) {
  return (
    <AriaDateSegment
      className={[DATE_SEGMENT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaDateSegment>
  )
}

/**
 * The chevron that opens the calendar. Use it as `DatePicker.Button`, inside a
 * `DatePicker.Group`.
 *
 * Exported as `DatePickerButton` only so tooling can resolve it; consume the compound form
 * `DatePicker.Button`.
 */
export function DatePickerButton({
  className,
  children,
  ...props
}: DatePickerButtonProps) {
  return (
    <AriaButton
      data-slot="icon-end"
      className={[DATE_TRIGGER, className].filter(Boolean).join(' ')}
      {...props}
    >
      <DateCaret />
    </AriaButton>
  )
}

/**
 * An affix at either end of the control. Group`.
 *
 * **Internal.** `DatePicker` draws one itself; it is not a published slot.
 */
export function DatePickerIcon({
  position = 'start',
  className,
  children,
  ...props
}: DatePickerIconProps) {
  return (
    <span
      data-slot={position === 'start' ? 'icon-start' : 'icon-end'}
      aria-hidden="true"
      className={[ICON, ICON_POSITIONS[position], className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children ?? (
        <svg viewBox="0 0 16 16" fill="none" className="h-full w-auto">
          <rect
            x="1.75"
            y="3.25"
            width="12.5"
            height="11"
            stroke="currentColor"
            strokeWidth="1.5"
          />
          <path
            d="M1.75 6.75h12.5M5.25 1.75v3M10.75 1.75v3"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
          />
        </svg>
      )}
    </span>
  )
}

/**
 * The calendar surface. *
 * **Internal.** `DatePicker` draws one itself; it is not a published slot.
 */
export function DatePickerPopover({
  className,
  children,
  ...props
}: DatePickerPopoverProps) {
  return (
    <AriaPopover
      data-slot="dropdown"
      className={[DATE_MENU, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaPopover>
  )
}

/**
 * The month heading, between the arrows. *
 * **Internal.** `DatePicker` draws one itself; it is not a published slot.
 */
export function DatePickerHeading({
  className,
  children,
  ...props
}: DatePickerHeadingProps) {
  const state = useContext(CalendarStateContext)
  const label = useVisibleRangeLabel(state?.visibleRange ?? null)

  return (
    // `aria-hidden`, because React Aria renders its own heading for assistive tech just above
    // this one — and that one is correct for any number of visible months. This is the copy the
    // eye reads, and React Aria's would otherwise be the one the eye reads instead, captioning a
    // two-month calendar with only its first month.
    <h2
      data-slot="heading"
      aria-hidden="true"
      className={[DATE_HEADING, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children ?? label}
    </h2>
  )
}

/**
 * The month grid. *
 * **Internal.** `DatePicker` draws one itself; it is not a published slot.
 */
export function DatePickerGrid({
  className,
  children,
  ...props
}: DatePickerGridProps) {
  return (
    <AriaCalendarGrid
      className={[className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaCalendarGrid>
  )
}

/**
 * One day. *
 * **Internal.** `DatePicker` draws one itself; it is not a published slot.
 */
export function DatePickerCell({
  className,
  children,
  ...props
}: DatePickerCellProps) {
  return (
    <AriaCalendarCell
      data-slot="cell"
      className={[DATE_CELL, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaCalendarCell>
  )
}

/**
 * The calendar, drawn whole: the month and its arrows, the weekday row, and the days.
 *
 * React Aria builds a calendar from a grid, a header and a body of render props — six elements
 * and two callbacks before a single day appears. None of that is a decision the consumer is
 * making, so it is drawn here whole and none of its parts is published.
 *
 * **Internal.** `DatePicker` draws one itself; it is not a published slot.
 */
export function DatePickerCalendar({
  className,
  children,
  ...props
}: DatePickerCalendarProps) {
  return (
    <AriaCalendar className={[className].filter(Boolean).join(' ')} {...props}>
      {children ?? (
        <DateCalendarChrome Heading={DatePickerHeading} Cell={DatePickerCell} />
      )}
    </AriaCalendar>
  )
}

/**
 * The guidance under the control. Use it as `DatePicker.Hint`.
 *
 * Exported as `DatePickerHint` only so tooling can resolve it; consume the compound form
 * `DatePicker.Hint`.
 */
export function DatePickerHint({
  className,
  children,
  ...props
}: DatePickerHintProps) {
  return (
    <AriaText
      slot="description"
      className={[HINT, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaText>
  )
}

/**
 * The message shown when the picker is `isInvalid`. Use it as `DatePicker.Error`.
 *
 * Exported as `DatePickerFieldError` only so tooling can resolve it; consume the compound form
 * `DatePicker.Error`.
 */
export function DatePickerFieldError({
  className,
  children,
  ...props
}: DatePickerFieldErrorProps) {
  return (
    <AriaFieldError
      className={[ERROR, className].filter(Boolean).join(' ')}
      {...props}
    >
      {children}
    </AriaFieldError>
  )
}

/**
 * Styled element. Not exported — `DatePicker` below is the public symbol, and docgen reads the
 * JSDoc from the *exported* declaration, not this one.
 */
function DatePickerRoot<T extends DateValue>({
  ref,
  size = 'md',
  className,
  children,
  ...props
}: DatePickerProps<T>) {
  return (
    <AriaDatePicker
      ref={ref}
      className={[DATE_ROOT, FIELD_SIZES[size], className]
        .filter(Boolean)
        .join(' ')}
      {...props}
    >
      {children}
      {/* A picker without a calendar is not a picker, so one is always drawn. It used to be skippable by
          passing a `Popover` of your own; that slot is gone, so the branch went with it. */}
      <DatePickerPopover>
        <DatePickerCalendar />
      </DatePickerPopover>
    </AriaDatePicker>
  )
}

/**
 * A date, typed or picked — the first component here with no sheet to copy, so it follows the
 * sheet's *language* rather than its markup: square, mono, the field's own hairline and focus, the
 * select's menu surface, and the accent kept for the day that is chosen.
 *
 * ```tsx
 * <DatePicker defaultValue={parseDate('2026-10-11')}>
 *   <DatePicker.Label>Starts</DatePicker.Label>
 *   <DatePicker.Group>
 *     <DatePicker.Input />
 *     <DatePicker.Button />
 *   </DatePicker.Group>
 *   <DatePicker.Hint>Your local time.</DatePicker.Hint>
 * </DatePicker>
 * ```
 *
 * **The calendar is drawn for you.** A picker without one is not a picker, so `DatePicker` opens
 * the same popover and month a `Select` opens its list on, and the field is the whole of the API
 * in the common case. **It is not replaceable**: the popover and the month it opens are internal, so the
 * field is the whole published surface. (`Select` does publish `Select.Popover`; this does not.)
 *
 * The value is a `DateValue`, not a string — `parseDate` reads an ISO date, and `onChange` hands
 * back the same shape. That is what keeps the field locale-aware: the segments, the month name
 * and the order they appear in all follow the locale rather than a format the code chose.
 *
 * **The calendar's parts are internal.** `DatePicker` draws the whole month itself, arrows and weekdays
 * included — React Aria builds one from six elements and two render props, and rearranging them is not a
 * decision a consumer of this component makes. What it publishes is the field's anatomy and nothing else:
 * `Label`, `Group`, `Input`, `Button`, `Hint`, `Error`. A component that offers every internal part as a
 * slot documents a surface nobody uses and cannot change without breaking people.
 */
export const DatePicker = Object.assign(DatePickerRoot, {
  Label: DatePickerLabel,
  Group: DatePickerGroup,
  Input: DatePickerInput,
  Button: DatePickerButton,
  Hint: DatePickerHint,
  Error: DatePickerFieldError,
})

import {
  Button as AriaButton,
  CalendarGrid as AriaCalendarGrid,
  CalendarGridBody as AriaCalendarGridBody,
  CalendarGridHeader as AriaCalendarGridHeader,
  CalendarHeaderCell as AriaCalendarHeaderCell,
  useLocale,
  CalendarMonthPicker,
  CalendarYearPicker,
} from 'react-aria-components'
import { DateFormatter, getLocalTimeZone } from '@internationalized/date'
import type { CalendarDate } from '@internationalized/date'

import { FIELD } from './field'

/**
 * The anatomy the two date components share. The same split as `field.ts`: everything that does
 * not differ lives here, and each component defines its own slot components over it, so Storybook
 * still documents `DatePicker.Label` as `DatePicker.Label` rather than as its neighbour's.
 *
 * The sheet has no date picker at all, so all of this is invention — but it is invention confined
 * to one file, which is what stops the second component from quietly becoming a fork of the first.
 */

/**
 * The field root. Identical for both, because it is the *field*: the same hairline, the same
 * height, the same teal on focus and on open.
 */
export const DATE_ROOT = [
  FIELD,
  'data-[open]:[--field-border:var(--color-primary)]',
  'data-[focused]:[--field-border:var(--color-primary)]',
  'data-[open]:[--field-hover:var(--color-primary)]',
  '[--dropdown-caret-rotate:0deg]',
  '[--dropdown-caret-ink:color-mix(in_oklch,var(--color-foreground)_50%,transparent)]',
  'data-[open]:[--dropdown-caret-rotate:180deg]',
  'data-[open]:[--dropdown-caret-ink:var(--color-primary)]',
  // A range's two date inputs sit inside one control, so the states that land on the root —
  // invalid, disabled — have no element of their own to dim or recolour. They are published here
  // and read by that control, the same arrangement `Select` uses for its trigger's border.
  'data-[invalid]:not-data-[focused]:[--field-border:var(--color-destructive)]',
  '[--date-control-opacity:1]',
  'data-[disabled]:[--date-control-opacity:0.4]',
].join(' ')

const DATE_CARET = [
  'h-1.5 w-2.5',
  'rotate-(--dropdown-caret-rotate) [color:var(--dropdown-caret-ink)]',
  'motion-safe:transition-[rotate,color] motion-safe:duration-(--duration-base) ease-pulse',
].join(' ')

export const DATE_TRIGGER = [
  'absolute top-1/2 right-3.5 z-10 flex size-3 -translate-y-1/2',
  'items-center justify-center',
  'cursor-pointer',
  'data-[disabled]:cursor-not-allowed',
  // 12px is the drawing, not the target — the pseudo-element makes it 24.
  'after:absolute after:content-[""] after:-inset-1.5',
  'outline-1 outline-offset-1 outline-transparent',
  'data-[focus-visible]:outline-ring',
].join(' ')

/** The sheet's `.ds-select-menu`, the same surface a select's list opens on. */
export const DATE_MENU = [
  'flex w-fit flex-col overflow-clip',
  'border border-border-strong bg-card rounded-xl p-2',
  'shadow-[0_12px_32px_rgba(0,0,0,.7)]',
].join(' ')

/**
 * One day in a month grid.
 *
 * Shared, because a day looks the same whether it arrived from `DatePicker`, `DateRangePicker` or a
 * `Calendar` sitting on the page — which is the whole reason this file exists. It was private to
 * `DatePicker` until a second component needed it.
 */
export const DATE_CELL: string = [
  'flex size-8 items-center justify-center rounded-md',
  'text-[13px] text-foreground/75 tabular-nums cursor-pointer select-none',
  'transition-colors duration-(--duration-fast) ease-pulse',
  'data-[hovered]:bg-foreground/7 data-[hovered]:text-foreground',
  'data-[pressed]:bg-foreground/15',
  'data-[outside-month]:text-foreground/30',
  // A day outside `minValue`/`maxValue` is `data-unavailable`; a day in a wholly disabled
  // calendar is `data-disabled`. Both mean the same thing to the eye, so both are marked.
  // Only days outside `minValue`/`maxValue` are struck through. A day either side of the month is
  // `data-disabled` too — React Aria disables everything outside the visible range — so striking
  // on `data-disabled` alone draws a line through the leading and trailing days of every month,
  // which says "unavailable" about a day that is merely in the wrong month.
  'data-[unavailable]:not-data-[outside-month]:text-foreground/25',
  'data-[unavailable]:not-data-[outside-month]:line-through',
  'data-[disabled]:not-data-[outside-month]:text-foreground/25',
  'data-[disabled]:not-data-[outside-month]:line-through',
  'data-[unavailable]:cursor-not-allowed data-[disabled]:cursor-not-allowed',
  'data-[today]:outline-1 data-[today]:outline-ring',
  'data-[selected]:bg-primary data-[selected]:text-ink',
  'data-[focus-visible]:outline-1 data-[focus-visible]:outline-offset-[3px]',
  'data-[focus-visible]:outline-ring',
].join(' ')

/**
 * A segment of a date. It takes the field's text colour and its placeholder weight, and marks the
 * one being edited with the same faint wash the sheet puts behind a hovered option rather than
 * with the accent — a field's focus is a teal *border*, and filling a segment in would say
 * "chosen" about one that is only being typed.
 */
export const DATE_SEGMENT = [
  'rounded-md px-0.5 outline-none',
  'text-foreground data-[placeholder]:text-foreground/35',
  'data-[focused]:bg-foreground/12 data-[focused]:text-foreground',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-40',
].join(' ')

/** The month's arrows. */
export const DATE_NAV = [
  'flex size-7 items-center justify-center rounded-md',
  'text-foreground/70 cursor-pointer',
  'transition-colors duration-(--duration-fast) ease-pulse',
  'data-[hovered]:bg-foreground/7 data-[hovered]:text-foreground',
  'data-[focus-visible]:outline-1 data-[focus-visible]:outline-offset-2',
  'data-[focus-visible]:outline-ring',
  'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-30',
].join(' ')

/** The sheet's `.ds-field-legend` and `.ds-select-group-label` are both this: 11–12px, spaced. */
export const DATE_HEADING =
  'text-[12px] uppercase tracking-[0.04em] text-muted-foreground tabular-nums'

export const DATE_WEEKDAY =
  'pb-1 text-[11px] uppercase tracking-[0.08em] text-foreground/45 font-normal'

/** The chevron that opens the calendar. */
export function DateCaret() {
  return (
    <svg
      viewBox="0 0 10 6"
      fill="none"
      aria-hidden="true"
      className={DATE_CARET}
    >
      <path
        d="M1 1L5 5L9 1"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

function Chevron({ className }: { className: string }) {
  return (
    <svg
      viewBox="0 0 10 6"
      fill="none"
      aria-hidden="true"
      className={className}
    >
      <path
        d="M1 1L5 5L9 1"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

/**
 * The month: its arrows, its heading, the weekday row and the days. Shared because it is pure
 * boilerplate — React Aria builds a calendar from two render props and a grid, and none of that
 * is a decision either component is making.
 *
 * It takes the two slots that genuinely differ. `Heading` is the month's name, which each
 * component exposes publicly and so must render as its own symbol; `Cell` is the day, where a
 * single date fills one and a range fills two and tints what lies between.
 */

/**
 * The month and the year, as controls rather than as a caption.
 *
 * **This is the difference between a calendar you page through and one you navigate.** Without them the
 * only way to reach March is to press the arrow eleven times, and a monitoring window is usually "last
 * month" rather than "next month" — so the heading is a control, not a label.
 *
 * Borderless and in the heading's own type, because the calendar's header is not a form: these read as
 * part of the title until you point at one, which is the convention a month name already has.
 * `appearance-none` drops the platform's own arrow for the same reason — the sheet has no native control
 * chrome anywhere in it.
 */
const DATE_PICKER = [
  'cursor-pointer appearance-none border-0 bg-transparent p-0',
  'font-mono text-[12px] font-medium tracking-[0.08em] uppercase text-foreground',
  'transition-colors duration-(--duration-fast) ease-pulse',
  'hover:text-primary',
  'outline-2 outline-offset-2 outline-transparent',
  'data-[focus-visible]:outline-ring focus-visible:outline-ring',
].join(' ')

/**
 * One of the two header pickers.
 *
 * **React Aria renders nothing here — it hands you the props and you render the `<select>`.** That is
 * why the component takes no `className` and its `children` is required: it is a render-prop control, not
 * a styled one. It yields `{ 'aria-label', value, onChange, items }`, and `items` must be pulled *out* of
 * what is spread onto the element, or React warns about an unknown `items` attribute.
 */
function DatePicker({
  Picker,
  format,
}: {
  Picker: typeof CalendarMonthPicker | typeof CalendarYearPicker
  format?: 'numeric' | '2-digit' | 'long' | 'short' | 'narrow'
}) {
  return (
    <Picker format={format}>
      {({ items, value, onChange, 'aria-label': ariaLabel }) => (
        // **`onChange` cannot be spread.** React Aria hands back a key — `onChange(key: Key | null)` —
        // and a `<select>` fires an event, so the two are adapted here rather than merged.
        <select
          aria-label={ariaLabel}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className={DATE_PICKER}
        >
          {items.map((item) => (
            <option key={item.id} value={item.id}>
              {item.formatted}
            </option>
          ))}
        </select>
      )}
    </Picker>
  )
}

export function DateCalendarChrome({
  Heading,
  Cell,
  months = 1,
}: {
  /** The month, or the months, in view — rendered only when there is more than one. */
  Heading: React.ComponentType
  Cell: (props: { date: CalendarDate }) => React.ReactElement
  /**
   * How many months to draw. A multi-month calendar needs one grid per month, each with its own
   * `offset` — without them the heading spans both months while the grid shows only the first,
   * which is worse than not offering the prop at all.
   */
  months?: number
}) {
  return (
    <>
      <header className="flex items-center justify-between pb-2">
        <AriaButton
          slot="previous"
          className={DATE_NAV}
          aria-label="Previous month"
        >
          <Chevron className="h-1.5 w-2.5 rotate-90" />
        </AriaButton>
        {months > 1 ? (
          // **A multi-month calendar keeps the heading, and a single-month one takes the pickers.**
          // The heading names the whole span — "March – April 2026" — and no pair of pickers can say a
          // range. A single month has nothing to span, so it can afford to be navigable instead.
          <Heading />
        ) : (
          <div className="flex items-center gap-1.5">
            <DatePicker Picker={CalendarMonthPicker} format="long" />
            <DatePicker Picker={CalendarYearPicker} />
          </div>
        )}
        <AriaButton slot="next" className={DATE_NAV} aria-label="Next month">
          <Chevron className="h-1.5 w-2.5 -rotate-90" />
        </AriaButton>
      </header>
      {/* Side by side, which is the whole point of asking for two: a range's ends are usually in
          different months, and stacking them puts a scroll or a page break between the two things
          being compared. React Aria's grids are tables, so they are block-level and stack unless
          something lays them out. */}
      <div className="flex gap-6">
        {Array.from({ length: months }, (_, i) => (
          <AriaCalendarGrid
            key={i}
            offset={{ months: i }}
            className="border-separate border-spacing-0"
          >
            <AriaCalendarGridHeader>
              {(day) => (
                <AriaCalendarHeaderCell className={DATE_WEEKDAY}>
                  {day}
                </AriaCalendarHeaderCell>
              )}
            </AriaCalendarGridHeader>
            <AriaCalendarGridBody>
              {(date) => <Cell date={date} />}
            </AriaCalendarGridBody>
          </AriaCalendarGrid>
        ))}
      </div>
    </>
  )
}

/**
 * The month, or the months, the calendar is showing.
 *
 * React Aria's `CalendarHeading` renders two nodes: an `aria-hidden` visual one and a separate
 * one for assistive tech. With more than one visible month they disagree — the hidden one, which
 * is the only one anybody sees and the one the consumer's `className` lands on, names just the
 * first month, so a two-month calendar is captioned "October 2026" above a grid showing November
 * as well. Rendering the text here from the calendar's own `visibleRange` gives one node, correct
 * for one month and for two.
 */
export function useVisibleRangeLabel(
  range: { start: CalendarDate; end: CalendarDate } | null,
) {
  const { locale } = useLocale()
  if (!range) return null

  // `formatRange` takes plain `Date`s, so the date values are converted first.
  const zone = getLocalTimeZone()
  const start = range.start.toDate(zone)
  const end = range.end.toDate(zone)
  const sameYear = range.start.year === range.end.year

  /**
   * **The two months are joined here rather than by `formatRange`, and that is a server-render fix.**
   * `Intl.DateTimeFormat#formatRange` puts the separator's spaces in the hands of the runtime's own
   * ICU, and the two runtimes are not the same ICU: measured, `en-GB` came out as
   * `March<U+2009>–<U+2009>April 2024` on this app's dev server and
   * `March<U+0020>–<U+0020>April 2024` in Chrome — the same words with different whitespace, which is
   * enough for React to throw the tree away and re-render it on every load of a page with a calendar on
   * it. Composing the label makes the caption the component's own typography, like everything else the
   * sheet draws, and leaves the environment with nothing to disagree about.
   */
  if (
    range.start.year === range.end.year &&
    range.start.month === range.end.month
  ) {
    return new DateFormatter(locale, { month: 'long', year: 'numeric' }).format(
      end,
    )
  }

  // The year once when both months are in it, which is what a range format would have said.
  const startLabel = new DateFormatter(locale, {
    month: 'long',
    ...(sameYear ? {} : { year: 'numeric' as const }),
  }).format(start)
  return `${startLabel} – ${new DateFormatter(locale, { month: 'long', year: 'numeric' }).format(end)}`
}
